<!DOCTYPE html>
<html lang="ar" dir="rtl">

<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>سحب المسابقة الكبرى - جوائز نقدية قيمة</title>
    <!-- خط تجوال وزخرفية -->
    <link href="https://fonts.googleapis.com/css2?family=Tajawal:wght@400;700;900&display=swap" rel="stylesheet">
    <!-- مكتبة الألعاب النارية والاحتفال -->
    <script src="https://cdn.jsdelivr.net/npm/canvas-confetti@1.6.0/dist/confetti.browser.min.js"></script>

    <style>
        :root {
            --gold-primary: #ffd700;
            --gold-secondary: #ffa500;
            --bg-dark: #0a0a0c;
            --card-bg: rgba(20, 20, 28, 0.85);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            font-family: 'Tajawal', sans-serif;
        }

        body {
            background: radial-gradient(circle at center, #1a1a2e 0%, var(--bg-dark) 100%);
            color: #fff;
            min-height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            padding: 20px;
            overflow-x: hidden;
        }

        .container {
            width: 100%;
            max-width: 900px;
            background: var(--card-bg);
            border: 2px solid rgba(255, 215, 0, 0.3);
            border-radius: 24px;
            padding: 40px 30px;
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.8), 0 0 30px rgba(255, 215, 0, 0.1);
            backdrop-filter: blur(10px);
            text-align: center;
            position: relative;
        }

        /* الهيدر والجوائز */
        .header h1 {
            font-size: 2.5rem;
            font-weight: 900;
            background: linear-gradient(135deg, #fff 0%, var(--gold-primary) 50%, var(--gold-secondary) 100%);
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            margin-bottom: 10px;
            text-shadow: 0 5px 15px rgba(0, 0, 0, 0.5);
        }

        .subtitle {
            font-size: 1.2rem;
            color: #d1d5db;
            margin-bottom: 25px;
        }

        .prize-badge {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            background: linear-gradient(90deg, rgba(255, 215, 0, 0.15), rgba(255, 165, 0, 0.15));
            border: 1px solid var(--gold-primary);
            padding: 8px 24px;
            border-radius: 50px;
            color: var(--gold-primary);
            font-weight: bold;
            font-size: 1.1rem;
            margin-bottom: 30px;
            box-shadow: 0 0 15px rgba(255, 215, 0, 0.2);
        }

        /* شاشة عرض الأسماء العشوائية */
        .display-box {
            background: #000;
            border: 3px solid var(--gold-primary);
            border-radius: 16px;
            height: 120px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-bottom: 30px;
            position: relative;
            overflow: hidden;
            box-shadow: inset 0 0 20px rgba(255, 215, 0, 0.2);
        }

        .name-text {
            font-size: 2.2rem;
            font-weight: 700;
            color: #fff;
            transition: all 0.1s ease;
            text-shadow: 0 0 10px rgba(255, 255, 255, 0.5);
        }

        .name-text.winner-anim {
            color: var(--gold-primary);
            font-size: 2.8rem;
            font-weight: 900;
            text-shadow: 0 0 20px var(--gold-primary);
            animation: pulse 0.5s infinite alternate;
        }

        @keyframes pulse {
            0% {
                transform: scale(1);
            }

            100% {
                transform: scale(1.05);
            }
        }

        /* أزرار التحكم */
        .controls {
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
            margin-bottom: 30px;
        }

        .btn {
            background: linear-gradient(135deg, var(--gold-primary), var(--gold-secondary));
            color: #000;
            border: none;
            padding: 16px 36px;
            font-size: 1.2rem;
            font-weight: 700;
            border-radius: 12px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 10px 20px rgba(255, 165, 0, 0.3);
        }

        .btn:hover {
            transform: translateY(-3px);
            box-shadow: 0 15px 25px rgba(255, 215, 0, 0.5);
        }

        .btn:disabled {
            background: #4b5563;
            color: #9ca3af;
            cursor: not-allowed;
            transform: none;
            box-shadow: none;
        }

        .btn-secondary {
            background: #1f2937;
            color: #fff;
            border: 1px solid rgba(255, 255, 255, 0.2);
            box-shadow: none;
        }

        .btn-secondary:hover {
            background: #374151;
            box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
        }

        /* منطقة قائمة الفائزين وإدخال الأسماء */
        .bottom-section {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 20px;
            text-align: right;
        }

        @media (max-width: 768px) {
            .bottom-section {
                grid-template-columns: 1fr;
            }
        }

        .panel {
            background: rgba(0, 0, 0, 0.4);
            border: 1px solid rgba(255, 255, 255, 0.1);
            border-radius: 12px;
            padding: 20px;
        }

        .panel h3 {
            color: var(--gold-primary);
            margin-bottom: 15px;
            font-size: 1.1rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        textarea {
            width: 100%;
            height: 120px;
            background: #111827;
            border: 1px solid #374151;
            border-radius: 8px;
            color: #fff;
            padding: 10px;
            resize: none;
            font-size: 0.95rem;
        }

        textarea:focus {
            outline: none;
            border-color: var(--gold-primary);
        }

        .winners-list {
            list-style: none;
            max-height: 120px;
            overflow-y: auto;
        }

        .winners-list li {
            background: rgba(255, 215, 0, 0.1);
            border-right: 3px solid var(--gold-primary);
            padding: 8px 12px;
            margin-bottom: 8px;
            border-radius: 4px;
            display: flex;
            justify-content: space-between;
            font-weight: bold;
        }

        .winners-list li span.rank {
            color: var(--gold-primary);
        }
    </style>
</head>

<body>

    <div class="container">
        <!-- هيدر المسابقة -->
        <div class="header">
            <h1>السحب على الجوائز النقدية الكبرى</h1>
            <p class="subtitle">تمتع بفرصة الفوز بـ إحدى الجوائز النقدية القيمة!</p>
            <div class="prize-badge">
                <span>💰</span>
                <span>سحب عشوائي لاختيار الفائزين</span>
            </div>
        </div>

        <!-- شاشة إظهار الأسماء -->
        <div class="display-box">
            <div id="nameDisplay" class="name-text">اضغط "بدء السحب" للبدء</div>
        </div>

        <!-- أزرار التحكم -->
        <div class="controls">
            <button id="startBtn" class="btn" onclick="startShuffle()">▶ بدء السحب</button>
            <button id="lockBtn" class="btn" onclick="lockWinner()" disabled>🎯 تثبيت الفائز</button>
            <button class="btn btn-secondary" onclick="resetAll()">🔄 إعادة ضبط</button>
        </div>

        <!-- الجزء السفلي: الأسماء والفائزين -->
        <div class="bottom-section">
            <!-- قائمة المشاركين -->
            <div class="panel">
                <h3>قائمة المشاركين <span id="countDisplay">(0)</span></h3>
                <textarea id="namesInput" placeholder="أدخل الأسماء هنا، اسم واحد في كل سطر..." oninput="updateParticipants()"></textarea>
            </div>

            <!-- قائمة الفائزين -->
            <div class="panel">
                <h3>🏆 قائمة الفائزين</h3>
                <ul id="winnersList" class="winners-list">
                    <!-- سيتم إضافة الفائزين هنا -->
                </ul>
            </div>
        </div>
    </div>

