            "زبد محمد قاسم العاقل",
            "مختار عبدالله محمد سعدالدين",
            "حميد حسين ابراهيم الملحاني",
            "فخر الدين محمد يحيى",
            "عبدالله عبدالباقي عبدة القباطي",
            "عمر عبدالرحمن عبدالله البطر",
            "عبده اللطيف محمد يحيى",
            "ياسر محمد علي الوضري",
            "سميره عبدالله محمد حنش",
            "بدريه احمد احمد علي",
            "هايل صالح علوي العواضي",
            "محمد طالب عبدالله علي",
            "علي محمد يحيى حسن",
            "محمد علي احمد الرازقي",
            "احمد مهدي ابراهيم صالح",
            "طه محبوب يحيى القصاري",
            "عمار حسين عبدالله الهلماني",
            "بسام ابراهيم حسين جابر",
            "محمد منصور محمد العزي",
            "محمد رياض يونس الارياني",
            "عيظة برك سهل الجابري",
            "هديل حسين محمود عاموه",
            "خالد محمد احمد الضبيبي",
            "وائل محمد محمد علي",
            "احمد محمد حسين ناصر",
            "فايز عبدربه سعيد العولقي",
            "ايوب محمد ايوب سيف",
            "احمد مرزوق زيد الشامي",
            "ملاك جميل علي العبسي",
            "إكرام احمد عبدالله الفقيه",
            "عبدالرحمن يحيى يحيى عاطف",
            "عبدالله علي عبدالله العمري",
            "احمد عبده ناصر حسين",
            "سليم احمد محمد الحبابي",
            "احمد صالح احمد الرياشي",
            "طه محمد علي الراشدي",
            "أصيل نشوان قاسم ناصر",
            "مهدي راشد ناجي حسن",
            "يوسف فواز يوسف الدهي",
            "سعد حسن سعد العماد",
            "فرحان مثنئ غالب الاحمدي"
        ];

        let participants = [];
        let shuffleInterval = null;
        let isShuffling = false;
        let winnersCount = 0;

        const nameDisplay = document.getElementById('nameDisplay');
        const namesInput = document.getElementById('namesInput');
        const startBtn = document.getElementById('startBtn');
        const lockBtn = document.getElementById('lockBtn');
        const winnersList = document.getElementById('winnersList');
        const countDisplay = document.getElementById('countDisplay');

        // التهيئة الأولية
        window.onload = () => {
            namesInput.value = defaultNames.join('\n');
            updateParticipants();
        };

        // تحديث قائمة المشاركين عند التعديل
        function updateParticipants() {
            const text = namesInput.value;
            participants = text.split('\n').map(n => n.trim()).filter(n => n !== "");
            countDisplay.innerText = `(${participants.length})`;
        }

        // بدء الفرز العشوائي
        function startShuffle() {
            if (participants.length === 0) {
                alert("يرجى إضافة أسماء المشاركين أولاً!");
                return;
            }

            isShuffling = true;
            nameDisplay.classList.remove('winner-anim');
            startBtn.disabled = true;
            lockBtn.disabled = false;
            namesInput.disabled = true;

            // تغيير الأسماء بسرعة عالية ليعطي انطباع الفرز العشوائي
            shuffleInterval = setInterval(() => {
                const randomIndex = Math.floor(Math.random() * participants.length);
                nameDisplay.innerText = participants[randomIndex];
            }, 50);
        }

        // تثبيت الفائز
        function lockWinner() {
            if (!isShuffling) return;

            clearInterval(shuffleInterval);
            isShuffling = false;

            // اختيار فائز عشوائي نهائي
            const winnerIndex = Math.floor(Math.random() * participants.length);
            const winnerName = participants[winnerIndex];

            // إظهار الفائز بتأثير بصري
            nameDisplay.innerText = `🎉 ${winnerName} 🎉`;
            nameDisplay.classList.add('winner-anim');

            // إضافة الفائز إلى القائمة
            winnersCount++;
            const li = document.createElement('li');
            li.innerHTML = `<span>${winnerName}</span> <span class="rank">الفائز #${winnersCount}</span>`;
            winnersList.prepend(li);

            // إزالة الفائز من قائمة المشاركين لتجنب تكراره في السحب القادم
            participants.splice(winnerIndex, 1);
            namesInput.value = participants.join('\n');
            countDisplay.innerText = `(${participants.length})`;

            // إطلاق الاحتفالات
            triggerConfetti();

            // ضبط حالة الأزرار للسحب التالي
            startBtn.disabled = false;
            lockBtn.disabled = true;
            namesInput.disabled = false;
        }

        // تأثير الألعاب النارية والورق الملون
        function triggerConfetti() {
            confetti({
                particleCount: 120,
                spread: 80,
                origin: {
                    y: 0.6
                },
                colors: ['#ffd700', '#ffa500', '#ffffff']
            });
        }

        // إعادة ضبط البرنامج
        function resetAll() {
            clearInterval(shuffleInterval);
            isShuffling = false;
            winnersCount = 0;
            winnersList.innerHTML = '';
            nameDisplay.classList.remove('winner-anim');
            nameDisplay.innerText = 'اضغط "بدء السحب" للبدء';

            startBtn.disabled = false;
            lockBtn.disabled = true;
            namesInput.disabled = false;

            namesInput.value = defaultNames.join('\n');
            updateParticipants();
        }
    </script>
</body>

</html>
